'use client';

// Generated by scripts/sync-from-web.mjs from Punji's web kit. Do not edit here:
// change it in Punji, then sync (CONTRIBUTING.md, "How the kit is kept in sync").
/**
 * The account area's company finder: one large, visible field (symbol or
 * name) with suggestions under it, ranked in memory over the build's
 * registry, so nothing is fetched while typing. Choosing a suggestion (click,
 * or ↑ ↓ then Enter) opens it; Enter on an exact symbol opens that; Esc clears,
 * then leaves. `/` focuses it when nothing else is being typed in and no
 * dialog is open (ahead of the shell's own `/`, which opens the command menu).
 *
 * Used by Fundamentals (its first run) and the dividend book's home.
 */
import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from 'react';

import { searchSymbols, type SymbolOption } from '../format/format.ts';

const TYPING = 'input, textarea, select, [contenteditable=""], [contenteditable="true"]';

export interface CompanySearchProps<T extends SymbolOption> {
  options: readonly T[];
  /** The visible label over the field ("Find any company"); also its accessible name. */
  label: string;
  placeholder: string;
  onOpen: (symbol: string) => void;
  /** The line under a suggestion's symbol (name · sector). */
  sub?: (o: T) => string;
  /** Small tags at a suggestion's end (Your holdings, Watching, …). */
  tags?: (o: T) => ReactNode;
  /** "No company matches “{q}”." */
  none: (q: string) => ReactNode;
  testId: string;
  /** The suggestions' test ids: `${optionTestId}-${SYMBOL}`. */
  optionTestId: string;
  listTestId?: string;
  /** Hide the label visually (it stays the field's name). */
  hideLabel?: boolean;
}

export function CompanySearch<T extends SymbolOption>({ options, label, placeholder, onOpen, sub, tags, none, testId, optionTestId, listTestId, hideLabel }: CompanySearchProps<T>) {
  const id = useId();
  const [query, setQuery] = useState('');
  const [index, setIndex] = useState(0);
  const input = useRef<HTMLInputElement>(null);
  const hits = useMemo(() => (query.trim() ? (searchSymbols(options, query, 8) as T[]) : []), [options, query]);
  const active = hits.length ? Math.min(index, hits.length - 1) : -1;

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== '/' || e.metaKey || e.ctrlKey || e.altKey || e.defaultPrevented) return;
      const target = e.target instanceof Element ? e.target : null;
      if (target?.closest(TYPING) || document.querySelector('[aria-modal="true"]')) return;
      e.preventDefault();
      input.current?.focus();
    };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, []);

  function onKeyDown(e: ReactKeyboardEvent<HTMLInputElement>) {
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && hits.length) {
      e.preventDefault();
      setIndex((active + (e.key === 'ArrowDown' ? 1 : -1) + hits.length) % hits.length);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const pick = active >= 0 ? hits[active] : null;
      const typed = query.trim().toUpperCase();
      if (pick) onOpen(pick.symbol);
      else if (typed && options.some((s) => s.symbol.toUpperCase() === typed)) onOpen(typed);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      if (query) {
        setQuery('');
        setIndex(0);
      } else input.current?.blur();
    }
  }

  const optId = (s: string) => `${id}-opt-${s}`;
  return (
    <div className="kit-cs-w">
      <label className={hideLabel ? 'kit-sr' : 'kit-cs-l'} htmlFor={`${id}-in`}>
        {label}
      </label>
      <div className="kit-cs">
        <svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.6" aria-hidden="true">
          <circle cx="7" cy="7" r="5" />
          <path d="M11 11l3.5 3.5" strokeLinecap="round" />
        </svg>
        <input
          id={`${id}-in`}
          ref={input}
          role="combobox"
          aria-expanded={query.trim().length > 0}
          aria-controls={`${id}-list`}
          aria-autocomplete="list"
          aria-activedescendant={active >= 0 ? optId(hits[active]!.symbol) : undefined}
          placeholder={placeholder}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setIndex(0);
          }}
          onKeyDown={onKeyDown}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="characters"
          spellCheck={false}
          enterKeyHint="go"
          data-testid={testId}
        />
        <kbd aria-hidden="true">/</kbd>
      </div>
      {query.trim() && (
        <div className="kit-cs-sugg" id={`${id}-list`} role="listbox" aria-label={label} data-testid={listTestId}>
          {hits.length === 0 ? (
            <p className="kit-cs-none" role="status">
              {none(query.trim())}
            </p>
          ) : (
            hits.map((s, i) => (
              <div
                key={s.symbol}
                id={optId(s.symbol)}
                role="option"
                aria-selected={i === active}
                className={`kit-cs-opt${i === active ? ' on' : ''}`}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => onOpen(s.symbol)}
                data-testid={`${optionTestId}-${s.symbol}`}
              >
                <span className="kit-cs-id">
                  <b>{s.symbol}</b>
                  <span>{sub ? sub(s) : s.name}</span>
                </span>
                {tags && <span className="kit-cs-tags">{tags(s)}</span>}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}
